import test from 'node:test';
import assert from 'node:assert/strict';
import React,{act} from 'react';
import {createServer} from 'vite';
import {fileURLToPath} from 'node:url';
import {JSDOM} from 'jsdom';
test('queue UI submits bounded configuration and explicit retry while keeping source titles escaped',async()=>{
 const vite=await createServer({configFile:false,root:fileURLToPath(new URL('../',import.meta.url)),server:{middlewareMode:true,watch:null},appType:'custom'}),dom=new JSDOM('<div id="root"></div>',{url:'http://localhost/'}),keys=['window','document','HTMLElement','IS_REACT_ACT_ENVIRONMENT'],before=Object.fromEntries(keys.map(k=>[k,globalThis[k]]));let root;
 try{Object.assign(globalThis,{window:dom.window,document:dom.window.document,HTMLElement:dom.window.HTMLElement,IS_REACT_ACT_ENVIRONMENT:true});const {createRoot}=await import('react-dom/client'),{ResearchPipeline}=await vite.ssrLoadModule('/src/integrated/Operations.jsx');root=createRoot(document.getElementById('root'));const calls=[],pipeline={enabled:true,settings:{version:3,dailyCalls:7,includeClues:false},callsInLast24Hours:2,comparisonUsage:{invocations:1,pairAttempts:3},counts:{failed:1},items:[{id:'fixture-id',title:'<script>合成新闻</script>',revision:2,status:'failed',topicId:'fixture-topic',reason:'来源待处理'}],relations:{counts:{failed:1,candidate:1},items:[{id:'relation-id',status:'failed',source:{id:'new',title:'新报道',version:2},target:{id:'old',title:'已有研究',version:3}},{id:'done',invocation:{id:'call',comparisons:3,index:1},status:'candidate',source:{id:'new',title:'新报道',version:2},target:{id:'old',title:'已有研究',version:3},scopes:['extracted-text','excerpt'],comparison:{relation:'unrelated',reason:'未见足够关联',left:{quote:'<script>新材料</script>'},right:{quote:'合成已有材料'}}}]},events:{counts:{failed:1,candidate:1},items:[{id:'event-job',kind:'dossier',title:'已选事项',topicId:'child',status:'failed',relationCoverage:{topicsIndexed:23,topicsTotal:23,selectedTopics:2}},{id:'empty-job',kind:'extract',title:'空拆分材料',topicId:'parent',status:'candidate',eventCount:0}]}};pipeline.clusters={items:[{id:'cluster-job',sourceTitle:'<script>新事项</script>',clusterTitle:'原事件簇',status:'completed',batchId:'cluster-batch',reusedPairs:3,inputCount:11,pairCount:55,counts:{candidate:48,queued:4,running:1,failed:1,interrupted:1}}]};const render=busy=>root.render(React.createElement(ResearchPipeline,{pipeline,busy,onChange:(...args)=>calls.push(args)}));await act(()=>render(false));assert.equal(document.querySelectorAll('script').length,0);assert.match(document.body.textContent,/过去24小时已调用 2 次/);assert.match(document.body.textContent,/关系比较 1 次调用 \/ 3 对尝试（含失败）/);assert.match(document.body.textContent,/同次模型调用共 3 对，本条为第 2 对/);assert.match(document.body.textContent,/复用 3 对历史比较/);assert.match(document.body.textContent,/11 份输入 · 比较结果 48\/55 对 · 等待 4 · 运行 1 · 失败 \/ 中断 2/);assert.match(document.body.textContent,/配对已结束，待核对/);assert.equal(document.querySelector('a').getAttribute('href'),'/?topic=fixture-topic');await act(()=>document.querySelector('input[type=checkbox]').click());await act(()=>document.querySelectorAll('input[type=checkbox]')[1].click());await act(()=>document.querySelector('form').dispatchEvent(new dom.window.Event('submit',{bubbles:true,cancelable:true})));assert.deepEqual(calls[0],['configure',{version:3,dailyCalls:7,includeClues:true,extractEvents:true}]);const retry=[...document.querySelectorAll('button')].find(b=>b.textContent==='重试此项');await act(()=>retry.click());assert.deepEqual(calls[1],['retry',{id:'fixture-id'}]);const relationRetry=[...document.querySelectorAll('button')].find(b=>b.textContent==='重试比较');await act(()=>relationRetry.click());assert.deepEqual(calls[2],['retry-relation',{id:'relation-id'}]);assert.match(document.body.textContent,/没有足够关联/);assert.match(document.body.textContent,/网页提取文本 \/ 摘录/);assert.equal(document.querySelectorAll('script').length,0);const eventRetry=[...document.querySelectorAll('button')].find(b=>b.textContent==='重试事项调用');await act(()=>eventRetry.click());assert.deepEqual(calls[3],['retry-event',{id:'event-job'}]);assert.match(document.body.textContent,/本次未发现可支持的具体事项/);assert.match(document.body.textContent,/0 个事项候选/);assert.match(document.body.textContent,/跨报道事项召回：23\/23 项；选取 2 项比较/);pipeline.events.items[0].relationCoverage={automatic:true,scanId:'scope',topicsIndexed:501,topicsTotal:501,recalledTopics:8,selectedTopics:3,remainingTopics:5,counts:{completed:1,queued:1,running:1},status:'pending'};await act(()=>render(false));assert.match(document.body.textContent,/命中 8 项 · 已安排 3 项 · 待安排 5 项/);assert.match(document.body.textContent,/已保存判断 1 · 等待比较 1 · 处理中 1/);assert.match(document.body.textContent,/无需逐项操作/);pipeline.events.items[0].relationCoverage={...pipeline.events.items[0].relationCoverage,status:'invalidated',reason:'输入已变化'};await act(()=>render(false));assert.match(document.body.textContent,/原范围已停止续查：输入已变化/);pipeline.events.items[0].stale=true;pipeline.relations.items[0].stale=true;await act(()=>render(false));assert(relationRetry.disabled);assert(eventRetry.disabled);assert.match(document.body.textContent,/依据已变化/);await act(()=>render(true));assert(document.querySelector('fieldset').disabled);assert([...document.querySelectorAll('button')].every(b=>b.disabled));
 }finally{if(root)await act(()=>root.unmount());for(const k of keys)if(before[k]===undefined)delete globalThis[k];else globalThis[k]=before[k];dom.window.close();await vite.close();}
});
